13	// toolCmd is one subprocess invocation: the binary and the arguments handed to
14	// it. Building it is pure, which is what makes the argument surface — the part
15	// that decides what a scanner is actually asked to do — testable without a
16	// scanner installed.
17	//
18	// It is also what the UI displays. Deriving the shown command and the executed
19	// one from the same value is the point: the two used to be built separately and
20	// had drifted (§1.3 D19).
21	type toolCmd struct {
22		Name string
23		Args []string
24	}
25	
26	// String renders the invocation as a shell command line, for logs and for the
27	// command the UI shows next to a scan.
28	func (c toolCmd) String() string {
29		if c.Name == "" {
30			return ""
31		}
32		return strings.Join(append([]string{c.Name}, c.Args...), " ")
33	}
34	
35	// exitError reports a tool that ran and exited non-zero. The code matters:
36	// both scanners use a non-zero exit to mean "I found something" rather than
37	// "I failed" — trivy for vulnerabilities, gitleaks for secrets — so callers
38	// have to tell the two apart.
39	type exitError struct {
40		Code   int
41		Stderr string
42	}
43	
44	func (e *exitError) Error() string {
45		if e.Stderr != "" {
46			return fmt.Sprintf("exit status %d: %s", e.Code, strings.TrimSpace(e.Stderr))
47		}
48		return fmt.Sprintf("exit status %d", e.Code)
49	}
50	
51	// commandRunner is the seam every subprocess in this package passes through.
52	//
53	// The package drives trivy and gitleaks as external processes, which makes it
54	// untestable without both installed and a repository to point them at. Routing
55	// through this interface lets tests exercise the argument building, the
56	// exit-code handling and the output parsing — where the defects live — against
57	// canned output.
58	type commandRunner interface {
59		// Run executes tc and returns what it wrote to stdout. Lines written to
60		// stderr are forwarded to progressFn as they arrive, which is how Trivy
61		// reports its database download. A tool that runs and exits non-zero
62		// returns its stdout along with an *exitError.
63		Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error)
64	}
65	
66	// cliRunner is the production commandRunner: it shells out to the real tools.
67	type cliRunner struct{}
68	
69	func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
70		cmd := exec.CommandContext(ctx, tc.Name, tc.Args...) //nolint:gosec // name is one of trivy/gitleaks/docker
71	
72		var stdout bytes.Buffer
73		cmd.Stdout = &stdout
74	
75		// Stderr is consumed two ways: streamed to progressFn while the tool runs,
76		// and kept so a failure can be reported with the tool's own diagnostic.
77		var stderr bytes.Buffer
78		if progressFn != nil {
79			pipe, err := cmd.StderrPipe()
80			if err == nil {
81				done := make(chan struct{})
82				go func() {
83					defer close(done)
84					sc := bufio.NewScanner(pipe)
85					for sc.Scan() {
86						line := strings.TrimSpace(sc.Text())
87						if line == "" {
88							continue
89						}
90						stderr.WriteString(line + "\n")
91						progressFn(line)
92					}
93				}()
94				if err := cmd.Start(); err != nil {
95					return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
96				}
97				<-done // drain stderr before Wait closes the pipe
98				return stdout.Bytes(), waitErr(tc.Name, cmd.Wait(), stderr.String())
99			}
100		}
101	
102		cmd.Stderr = &stderr
103		if err := cmd.Start(); err != nil {
104			return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
105		}
106		return stdout.Bytes(), waitErr(tc.Name, cmd.Wait(), stderr.String())
107	}
108	
109	// waitErr turns a non-zero exit into an *exitError carrying the code, and
110	// leaves anything else (a killed process, a broken pipe) as it is.
111	func waitErr(name string, err error, stderr string) error {
112		if err == nil {
113			return nil
114		}
115		var exitErr *exec.ExitError
116		if errors.As(err, &exitErr) {
117			if stderr == "" {
118				stderr = string(exitErr.Stderr)
119			}
120			return &exitError{Code: exitErr.ExitCode(), Stderr: stderr}
121		}
122		return fmt.Errorf("%s failed: %w", name, err)
123	}
124	
125	// runner is swapped by tests. Production code never reassigns it, so the
126	// package stays safe to call concurrently; tests that swap it must not run in
127	// parallel.
128	var runner commandRunner = cliRunner{}
