1	package scan
2	
3	import (
4		"fmt"
5		"path/filepath"
6		"strings"
7	)
8	
9	// Building a Trivy invocation is pure: the same inputs produce the command that
10	// is run and the command that is shown. Keeping the two derived from one
11	// builder is what stops them drifting apart (§1.3 D19).
12	
13	// containerScanPath is where a scanned directory is mounted inside the tool's
14	// container, so the argument passed to the tool is never the host path.
15	const containerScanPath = "/scan"
16	
17	// containerOutputPath is where a writable output directory is mounted.
18	const containerOutputPath = "/output"
19	
20	// dockerSocketMount lets a containerised Trivy inspect images held by the host
21	// daemon. It is a broad grant, so it is only made when there is no Trivy server
22	// to do the work instead.
23	const dockerSocketMount = "/var/run/docker.sock:/var/run/docker.sock:ro"
24	
25	// trivyArgs builds a vulnerability or license scan.
26	func trivyArgs(target string, targetType TargetType, licenseMode bool, source ToolSource,
27		image, server string, ignoreUnfixed, ignoreEOL bool) (toolCmd, error) {
28		var args []string
29	
30		switch targetType {
31		case TargetDirectory:
32			args = []string{"fs", "--format", "json"}
33			if licenseMode {
34				args = append(args, "--scanners", "license")
35			} else {
36				args = append(args, "--scanners", "vuln")
37			}
38		case TargetImage:
39			args = []string{"image", "--format", "json"}
40		default:
41			return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
42		}
43	
44		if server != "" {
45			args = append(args, "--server", server)
46		}
47		if ignoreUnfixed {
48			args = append(args, "--ignore-unfixed")
49		}
50		if ignoreEOL {
51			args = append(args, "--ignore-status", "end_of_life")
52		}
53	
54		return wrapTrivy(args, target, targetType, source, image, server), nil
55	}
56	
57	// trivyMisconfigArgs builds a misconfiguration scan. It reads configuration
58	// files rather than a package manifest, so it applies to both target types.
59	func trivyMisconfigArgs(target string, targetType TargetType, source ToolSource,
60		image, server string, ignoreEOL bool) (toolCmd, error) {
61		var args []string
62	
63		switch targetType {
64		case TargetDirectory:
65			args = []string{"fs", "--format", "json", "--scanners", "misconfig"}
66		case TargetImage:
67			args = []string{"image", "--format", "json", "--scanners", "misconfig"}
68		default:
69			return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
70		}
71	
72		if server != "" {
73			args = append(args, "--server", server)
74		}
75		if ignoreEOL {
76			args = append(args, "--ignore-status", "end_of_life")
77		}
78	
79		return wrapTrivy(args, target, targetType, source, image, server), nil
80	}
81	
82	// sbomArgs builds a CycloneDX SBOM generation and returns the host path the
83	// file will end up at, which is not the path Trivy is given in Docker mode.
84	func sbomArgs(target string, targetType TargetType, source ToolSource,
85		image, server, outputDir string) (toolCmd, string, error) {
86		name := sbomFileName(target, targetType)
87	
88		var hostPath string
89		switch {
90		case outputDir != "":
91			hostPath = filepath.Join(outputDir, name)
92		case targetType == TargetDirectory:
93			hostPath = filepath.Join(target, name)
94		case targetType == TargetImage:
95			hostPath = name
96		default:
97			return toolCmd{}, "", fmt.Errorf("unsupported target type: %s", targetType)
98		}
99	
100		if source != ToolSourceDocker {
101			args := []string{sbomSubcommand(targetType), "--format", "cyclonedx", "--output", hostPath}
102			if server != "" {
103				args = append(args, "--server", server)
104			}
105			return toolCmd{Name: "trivy", Args: append(args, target)}, hostPath, nil
106		}
107	
108		// In Docker mode the output directory has to be writable, so the read-only
109		// mount used elsewhere does not apply to it.
110		var mounts []string
111		var containerOut string
112		switch {
113		case targetType == TargetDirectory && outputDir != "":
114			mounts = []string{"-v", target + ":" + containerScanPath + ":ro", "-v", outputDir + ":" + containerOutputPath}
115			containerOut = containerOutputPath + "/" + name
116		case targetType == TargetDirectory:
117			mounts = []string{"-v", target + ":" + containerScanPath}
118			containerOut = containerScanPath + "/" + name
119		default:
120			if server == "" {
121				mounts = append(mounts, "-v", dockerSocketMount)
122			}
123			mountDir := outputDir
124			if mountDir == "" {
125				mountDir = "."
126			}
127			mounts = append(mounts, "-v", mountDir+":"+containerOutputPath)
128			containerOut = containerOutputPath + "/" + name
129		}
130	
131		args := []string{sbomSubcommand(targetType), "--format", "cyclonedx", "--output", containerOut}
132		if server != "" {
133			args = append(args, "--server", server)
134		}
135		if targetType == TargetDirectory {
136			args = append(args, containerScanPath)
137		} else {
138			args = append(args, target)
139		}
140	
141		dockerArgs := append([]string{"run", "--rm"}, mounts...)
142		dockerArgs = append(dockerArgs, trivyImage(image))
143		return toolCmd{Name: "docker", Args: append(dockerArgs, args...)}, hostPath, nil
144	}
145	
146	func sbomSubcommand(targetType TargetType) string {
147		if targetType == TargetImage {
148			return "image"
149		}
150		return "fs"
151	}
152	
153	// sbomFileName keeps an image's SBOM identifiable while staying a legal
154	// filename — a tag reference carries "/" and ":".
155	func sbomFileName(target string, targetType TargetType) string {
156		if targetType == TargetImage {
157			return fmt.Sprintf("sbom-%s.json", strings.NewReplacer("/", "_", ":", "_").Replace(target))
158		}
159		return "sbom-report.json"
160	}
161	
162	// wrapTrivy turns tool arguments into the invocation to run: either trivy
163	// directly, or docker run with the target mounted and the tool arguments
164	// appended after the image.
165	func wrapTrivy(args []string, target string, targetType TargetType, source ToolSource, image, server string) toolCmd {
166		if source != ToolSourceDocker {
